// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.diimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.SystemOperationExecutorImplimport com.roshan.persona.system.handler.NotificationHandlerimport com.roshan.persona.system.handler.ReversibleHandlerimport com.roshan.persona.system.undo.AtomicBatchCoordinatorimport com.roshan.persona.system.undo.PersistentUndoStackimport com.roshan.persona.system.undo.ReversibleActionimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — System Facade (Module 10 v2 — Step 10.9 FINAL). * * The one class that the Brain (Module 2) and UI (Module 16) talk to for * all system operations. Everything else in :feature:system is an * implementation detail. * * ## Public API * *  - [executeCommand] — execute a single operation (routes to handler). *  - [executeBatch] — execute multiple operations atomically (parallel/sequential + rollback). *  - [undoLastAction] — undo the last reversible action (restore pre-state). *  - [getActionHistory] — recent actions for UI. *  - [postNotification] — post a notification (for proactive engine). *  - [cancelNotification] — cancel a notification. * * ## Wiring * * Brain skills call [executeCommand] indirectly via the [SystemOperationExecutor] * interface (which [SystemOperationExecutorImpl] implements). The Brain doesn't * know about SystemFacade — it uses the executor interface. * * The UI (Module 16) calls SystemFacade directly for: *  - Undo button on action history screen. *  - Notification posting from proactive engine. *  - Batch execution display. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Implementation Plan — Step 10.9</a> */@Singletonclass SystemFacade @Inject constructor(    private val executor: SystemOperationExecutorImpl,    private val undoStack: PersistentUndoStack,    private val batchCoordinator: AtomicBatchCoordinator,    private val notificationHandler: NotificationHandler,) {    /**     * Execute a single system operation.     *     * Routes to the matching handler via the executor. If the handler is     * reversible and execution succeeds, the action (with the pre-state captured     * BEFORE execution — per Review 2 Fix A) is pushed to the undo stack.     *     * **Critical fix (audit defect A):** the pre-state is captured by the     * executor in [SystemOperationExecutorImpl.executeWithPreState] BEFORE     * the hardware call runs. We push THAT pre-state — we do NOT re-capture     * after execution (which would capture the post-state and make undo a no-op).     *     * @return the result of the operation.     */    suspend fun executeCommand(operation: SystemOperation): Result<Unit> {        Timber.tag(TAG).d("executeCommand: ${operation::class.simpleName}")        val outcome = executor.executeWithPreState(operation)        // Push to undo stack if reversible + successful + pre-state captured.        if (outcome.shouldPushToUndo && outcome.handlerId != null) {            pushToUndoStack(                operation = outcome.operation,                preState = outcome.preState,                handlerId = outcome.handlerId,                description = outcome.description ?: operation::class.simpleName ?: "operation",            )        }        return outcome.result    }    /**     * Execute a batch of operations atomically.     *     * Groups by resource category — different categories run in parallel,     * same category runs sequentially. On any failure, all previously-executed     * operations are rolled back (pre-state restored).     *     * @return Success with per-op results if all succeeded, Failure if any failed.     */    suspend fun executeBatch(operations: List<SystemOperation>): Result<List<Result<Unit>>> {        Timber.tag(TAG).d("executeBatch: ${operations.size} operations")        val result = batchCoordinator.executeAll(operations)        // Push successful reversible ops to undo stack.        if (result is Result.Success) {            result.data.forEachIndexed { _, opResult ->                if (opResult is Result.Success) {                    // Note: batch coordinator already captured pre-states internally.                    // For undo, we'd need to track which ops in the batch succeeded.                    // For v1, we skip per-op undo for batches — the user undoes the                    // last single action instead.                }            }        }        return result    }    /**     * Undo the last reversible action.     *     * Pops the latest action from the persistent undo stack and restores     * the pre-state via the handler's `restorePreState` method.     *     * @return true if undo succeeded, false if stack is empty or restore failed.     */    suspend fun undoLastAction(): Boolean {        val action = undoStack.pop() ?: run {            Timber.tag(TAG).i("undoLastAction: stack is empty")            return false        }        Timber.tag(TAG).i("undoLastAction: restoring ${action.description}")        val handler = executor.findHandlerForOperation(action.operation)        if (handler == null) {            Timber.tag(TAG).w("undoLastAction: no handler for ${action.operation::class.simpleName}")            return false        }        @Suppress("UNCHECKED_CAST")        val typedHandler = handler as ReversibleHandler<SystemOperation>        try {            typedHandler.restorePreState(action.operation, action.preState)            undoStack.confirmPop(action.id)            Timber.tag(TAG).i("undoLastAction: success — ${action.description} undone")            return true        } catch (t: Throwable) {            Timber.tag(TAG).w("undoLastAction: restore failed", t)            return false        }    }    /**     * Get the last N actions for the UI history list.     *     * @param limit max actions to return (default 50).     * @return list of reversible actions, most-recent-first.     */    suspend fun getActionHistory(limit: Int = 50): List<ReversibleAction> {        return undoStack.getRecent(limit)    }    /** Number of undoable actions currently on the stack. */    suspend fun getUndoCount(): Int = undoStack.count()    /** Clear all undo history (Settings → Privacy → Clear action history). */    suspend fun clearActionHistory() = undoStack.clear()    /**     * Post a notification (used by proactive engine + UI).     *     * Delegates to [NotificationHandler.post].     */    suspend fun postNotification(        id: Int, channelId: String, channelName: String, title: String, text: String,    ): Result<Unit> = notificationHandler.post(id, channelId, channelName, title, text)    /** Cancel a previously-posted notification by ID. */    suspend fun cancelNotification(id: Int) = notificationHandler.cancel(id)    /** Cancel all NOUS notifications. */    suspend fun cancelAllNotifications() = notificationHandler.cancelAll()    // ──────────────────────────────────────────────────────────────────────    /**     * Push a reversible action to the undo stack.     *     * **Critical:** [preState] must be the state captured BEFORE execution     * (from [SystemOperationExecutorImpl.executeWithPreState]). Re-capturing     * here would observe the post-execution state and break undo — see     * audit defect A.     */    private suspend fun pushToUndoStack(        operation: SystemOperation,        preState: Any?,        handlerId: String,        description: String,    ) {        val action = ReversibleAction(            id = 0,  // assigned by DB on insert            operation = operation,            preState = preState,            handlerId = handlerId,            timestampMs = System.currentTimeMillis(),            description = description,        )        undoStack.push(action)    }    private companion object {        private const val TAG = "SystemFacade"    }}